import {test} from 'node:test';
import assert from 'node:assert/strict';
import {createOrder} from '../src/order.mjs';

test('hidden check', async () => {
  for (const quantity of [0, -1, 1.5, '2']) assert.throws(() => createOrder({items: [{price: 1000, quantity}]}), /invalid_quantity/);
  assert.equal(createOrder({items: [{price: 1000, quantity: 2}]}).subtotal, 2000);
  assert.throws(() => createOrder({items: []}), /empty_order/);
});
